// Ported from the Node app's Sequelize model MessageTemplate (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class MessageTemplateConfiguration : IEntityTypeConfiguration<MessageTemplate>
{
    public void Configure(EntityTypeBuilder<MessageTemplate> builder)
    {
        builder.ToTable("message_templates", t =>
        {
            t.HasCheckConstraint("CK_message_templates_channel", "[channel] IN (N'email', N'sms')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Channel).HasColumnName("channel").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Subject).HasColumnName("subject").HasColumnType("nvarchar(200)").HasMaxLength(200);
        builder.Property(e => e.Body).HasColumnName("body").HasColumnType("nvarchar(max)").IsRequired();
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
